head.b:skin:
/* =============================================
   CSS 변수 (다크/라이트 모드)
   ============================================= */
:root {
  --background-color: #0f172a;
  --bg-gradient: radial-gradient(circle at top left, #1e293b, #0f172a);
  --text-color: #f1f5f9;
  --text-muted: #94a3b8;
  --primary-color: #38bdf8;
  --primary-glow: rgba(56, 189, 248, 0.4);
  --error-color: #f43f5e;
  --success-color: #10b981;
  --input-background: #1e293b;
  --input-border: #334155;
  --button-hover: #0ea5e9;
  --card-background: rgba(30, 41, 59, 0.7);
  --ad-background: rgba(255, 255, 255, 0.03);
  --ad-text: #475569;
  --nav-bg: rgba(15, 23, 42, 0.9);
}
body.light-mode {
  --background-color: #f8fafc;
  --bg-gradient: radial-gradient(circle at top left, #ffffff, #f1f5f9);
  --text-color: #1e293b;
  --text-muted: #64748b;
  --primary-color: #0284c7;
  --primary-glow: rgba(2, 132, 199, 0.2);
  --error-color: #e11d48;
  --success-color: #059669;
  --input-background: #ffffff;
  --input-border: #e2e8f0;
  --button-hover: #0369a1;
  --card-background: rgba(255, 255, 255, 0.95);
  --ad-background: rgba(0, 0, 0, 0.05);
  --nav-bg: rgba(255, 255, 255, 0.9);
}

/* =============================================
   기본 리셋 & 바디
   ============================================= */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--background-color);
  color: var(--text-color);
  line-height: 1.7;
  background-image: var(--bg-gradient);
  background-attachment: fixed;
  transition: background 0.3s ease;
  overflow-x: hidden;
}

/* =============================================
   헤더 & 네비게이션
   ============================================= */
header {
  position: sticky; top: 0; width: 100%;
  background: var(--nav-bg);
  backdrop-filter: blur(15px);
  z-index: 1000;
  border-bottom: 1px solid var(--input-border);
  padding: 1rem 0;
}
nav {
  max-width: 1200px; margin: 0 auto;
  display: flex; justify-content: space-between; align-items: center;
  padding: 0 2rem; position: relative;
}
.logo {
  font-weight: 900; font-size: 1.5rem; color: var(--primary-color);
  text-decoration: none; display: flex; align-items: center; gap: 0.5rem;
  flex-shrink: 0;
}
.nav-links {
  display: flex; gap: 1.5rem; list-style: none; align-items: center;
}
.nav-links a {
  text-decoration: none; color: var(--text-color); font-size: 0.95rem;
  font-weight: 600; transition: all 0.2s; cursor: pointer; opacity: 0.8;
}
.nav-links a:hover, .nav-links a.active { color: var(--primary-color); opacity: 1; }

/* 햄버거 버튼 */
.hamburger {
  display: none;
  background: var(--input-background);
  border: 1px solid var(--input-border);
  color: var(--text-color);
  width: 45px; height: 45px;
  border-radius: 12px; cursor: pointer;
  align-items: center; justify-content: center;
  font-size: 1.3rem; transition: all 0.2s;
  flex-shrink: 0;
}
.hamburger:hover { border-color: var(--primary-color); color: var(--primary-color); }

/* =============================================
   컨테이너 & 카드
   ============================================= */
.container {
  max-width: 1000px; margin: 2rem auto; padding: 0 1.5rem;
  display: flex; flex-direction: column; align-items: center; gap: 2.5rem;
}
.ad-wrapper {
  width: 100%; min-height: 100px; margin: 0.5rem 0; text-align: center;
  overflow: hidden; background: var(--ad-background); border-radius: 12px;
  border: 1px dashed var(--input-border);
  display: flex; align-items: center; justify-content: center;
}
main, .info-section, .partnership-section {
  text-align: left; background: var(--card-background); padding: 4rem;
  border-radius: 32px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5);
  width: 100%; max-width: 900px;
  backdrop-filter: blur(20px); border: 1px solid var(--input-border);
}

/* =============================================
   타이포그래피
   ============================================= */
h1 {
  font-size: 2.8rem; font-weight: 900; margin-bottom: 1.5rem; letter-spacing: -0.05em;
  background: linear-gradient(to right, var(--primary-color), #818cf8);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  text-align: center; line-height: 1.2;
}
h2 {
  color: var(--primary-color); margin: 3rem 0 1.5rem; font-size: 2rem;
  border-bottom: 2px solid var(--input-border); padding-bottom: 0.5rem; font-weight: 800;
}
h3 {
  color: var(--text-color); margin: 2rem 0 1rem; font-size: 1.4rem;
  font-weight: 700; display: flex; align-items: center; gap: 0.75rem;
}
p { color: var(--text-muted); margin-bottom: 1.25rem; font-size: 1.1rem; }
.lead {
  color: var(--text-muted); margin-bottom: 3rem; font-size: 1.3rem;
  text-align: center; max-width: 700px; margin-left: auto; margin-right: auto;
}

/* =============================================
   폼 스타일
   ============================================= */
.form-group { margin-bottom: 1.5rem; display: flex; flex-direction: column; gap: 0.5rem; }
.form-group label { font-weight: 600; color: var(--text-color); font-size: 0.95rem; }
input, textarea {
  padding: 1.25rem; border: 2px solid var(--input-border); border-radius: 16px;
  background: var(--input-background); color: var(--text-color); font-size: 1.1rem;
  outline: none; transition: all 0.3s cubic-bezier(0.4,0,0.2,1); width: 100%;
}
input:focus, textarea:focus {
  border-color: var(--primary-color); box-shadow: 0 0 0 4px var(--primary-glow); transform: translateY(-2px);
}
button[type="submit"], .submit-btn {
  padding: 1.25rem; border: none; border-radius: 16px; background: var(--primary-color);
  color: #fff; font-size: 1.2rem; font-weight: 800; cursor: pointer; transition: all 0.3s;
  width: 100%; margin-top: 1rem; box-shadow: 0 10px 15px -3px var(--primary-glow);
}
button[type="submit"]:hover, .submit-btn:hover {
  background: var(--button-hover); transform: translateY(-3px); box-shadow: 0 20px 25px -5px var(--primary-glow);
}

/* =============================================
   체커 서브탭 (비밀번호 | 이메일)
   ============================================= */
.checker-tabs {
  display: flex; gap: 0.75rem; margin-bottom: 2.5rem;
  background: var(--input-background); padding: 0.5rem;
  border-radius: 16px; border: 1px solid var(--input-border);
}
.checker-tab-btn {
  flex: 1; padding: 0.85rem 1rem; border: none; border-radius: 12px;
  background: transparent; color: var(--text-muted);
  font-size: 1rem; font-weight: 700; cursor: pointer; transition: all 0.2s;
}
.checker-tab-btn.active {
  background: var(--primary-color); color: #fff; box-shadow: 0 4px 12px var(--primary-glow);
}
.checker-content { display: none; }
.checker-content.active { display: block; animation: fadeIn 0.3s ease; }

/* =============================================
   비밀번호 강도 측정기
   ============================================= */
.strength-meter { margin-top: 1rem; display: none; }
.strength-meter.visible { display: block; }
.strength-bar-track {
  height: 8px; background: var(--input-border); border-radius: 99px;
  margin-bottom: 0.6rem; overflow: hidden;
}
.strength-bar-fill {
  height: 100%; border-radius: 99px; transition: width 0.3s, background 0.3s; width: 0%;
}
.strength-label { font-size: 0.9rem; font-weight: 700; margin-bottom: 0.75rem; }
.strength-criteria { display: grid; grid-template-columns: 1fr 1fr; gap: 0.5rem; }
.criteria-item {
  font-size: 0.82rem; color: var(--text-muted);
  display: flex; align-items: center; gap: 0.5rem; transition: color 0.2s;
}
.criteria-item.met { color: var(--success-color); }
.criteria-dot {
  width: 7px; height: 7px; border-radius: 50%; background: var(--input-border);
  flex-shrink: 0; transition: background 0.2s;
}
.criteria-item.met .criteria-dot { background: var(--success-color); }

/* =============================================
   이메일 체크 안내 박스
   ============================================= */
.email-info-box {
  background: rgba(56,189,248,0.05); border: 1px solid var(--primary-color);
  border-radius: 16px; padding: 1.25rem 1.5rem; margin-bottom: 2rem;
  font-size: 0.95rem; color: var(--text-muted); line-height: 1.6;
}
.email-info-box strong { color: var(--primary-color); }

/* =============================================
   뉴스 스타일
   ============================================= */
.news-feed { display: flex; flex-direction: column; gap: 2rem; }
.news-item { border-left: 4px solid var(--primary-color); padding-left: 1.5rem; margin-bottom: 1rem; }
.news-date { font-size: 0.85rem; color: var(--primary-color); font-weight: 700; margin-bottom: 0.5rem; display: block; }
.news-item h4 { font-size: 1.3rem; margin-bottom: 0.75rem; color: var(--text-color); }
.news-tag {
  display: inline-block; font-size: 0.72rem; font-weight: 800; padding: 0.2rem 0.6rem;
  border-radius: 6px; margin-bottom: 0.6rem; letter-spacing: 0.05em;
}
.tag-critical { background: rgba(244,63,94,0.15); color: #f43f5e; }
.tag-warning  { background: rgba(234,179,8,0.15);  color: #eab308; }
.tag-info     { background: rgba(56,189,248,0.15);  color: var(--primary-color); }

/* =============================================
   FAQ 스타일
   ============================================= */
.faq-container { display: flex; flex-direction: column; gap: 1.5rem; }
.faq-item {
  background: rgba(255,255,255,0.02); padding: 2rem; border-radius: 20px;
  border: 1px solid var(--input-border);
}
.faq-item h4 { color: var(--primary-color); margin-bottom: 1rem; font-size: 1.2rem; }

/* =============================================
   신뢰 배지
   ============================================= */
.trust-badge-container {
  display: flex; justify-content: center; gap: 3rem; margin: 3rem 0; flex-wrap: wrap;
}
.trust-badge { display: flex; flex-direction: column; align-items: center; text-align: center; width: 150px; }
.trust-icon { font-size: 2.5rem; margin-bottom: 1rem; }

/* =============================================
   content-list (가이드용 리스트)
   ============================================= */
.content-list {
  list-style: none; margin: 1.25rem 0 2rem;
  display: flex; flex-direction: column; gap: 0.85rem;
}
.content-list li {
  padding: 1rem 1.25rem; background: rgba(255,255,255,0.02);
  border-radius: 12px; border-left: 3px solid var(--primary-color);
  color: var(--text-muted); font-size: 1rem;
}

/* =============================================
   푸터
   ============================================= */
footer {
  width: 100%; padding: 5rem 2rem; background: var(--nav-bg);
  border-top: 1px solid var(--input-border); margin-top: 5rem;
}
.footer-content {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: 2fr 1fr; gap: 4rem;
}
.copyright { margin-top: 4rem; text-align: center; font-size: 0.9rem; color: var(--text-muted); opacity: 0.6; }

/* =============================================
   페이지 섹션 전환 애니메이션
   ============================================= */
.page-section { display: none; animation: fadeIn 0.5s ease-out; }
.page-section.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* =============================================
   테마 토글
   ============================================= */
.theme-toggle {
  background: var(--input-background); border: 1px solid var(--input-border);
  color: var(--text-color); width: 45px; height: 45px; border-radius: 12px;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem; transition: all 0.2s;
}

/* =============================================
   모바일 반응형
   ============================================= */
@media (max-width: 768px) {
  .hamburger { display: flex; }
  .nav-links {
    display: none;
    position: absolute; top: 100%; left: 0; right: 0;
    flex-direction: column; align-items: flex-start;
    background: var(--nav-bg); padding: 1rem 2rem;
    border-bottom: 1px solid var(--input-border);
    gap: 0.75rem; backdrop-filter: blur(15px); z-index: 999;
  }
  .nav-links.open { display: flex; }
  main, .info-section, .partnership-section { padding: 2rem 1.5rem; border-radius: 20px; }
  h1 { font-size: 1.9rem; }
  h2 { font-size: 1.5rem; }
  .trust-badge-container { gap: 1.5rem; }
  .strength-criteria { grid-template-columns: 1fr; }
  .footer-content { grid-template-columns: 1fr; gap: 2rem; }
  .checker-tab-btn { font-size: 0.88rem; padding: 0.75rem 0.5rem; }
}
@media (max-width: 480px) {
  h1 { font-size: 1.6rem; }
  .lead { font-size: 1.1rem; }
  .container { padding: 0 1rem; }
}

b:includable.script:
//

/* ----- 섹션 전환 ----- */
function showSection(id) {
  document.querySelectorAll('.page-section').forEach(function(s){ s.classList.remove('active'); });
  document.getElementById(id).classList.add('active');
  document.querySelectorAll('.nav-links a').forEach(function(a){ a.classList.remove('active'); });
  var targetNav = document.getElementById('nav-' + id);
  if (targetNav) targetNav.classList.add('active');
  window.scrollTo({ top: 0, behavior: 'smooth' });
  // 모바일 메뉴 닫기
  document.getElementById('nav-menu').classList.remove('open');
}

/* ----- 체커 서브탭 전환 ----- */
function switchCheckerTab(tab) {
  document.querySelectorAll('.checker-tab-btn').forEach(function(b){ b.classList.remove('active'); });
  document.querySelectorAll('.checker-content').forEach(function(c){ c.classList.remove('active'); });
  document.getElementById('checker-' + tab).classList.add('active');
  document.getElementById('ctab-' + tab).classList.add('active');
}

/* ----- 햄버거 메뉴 ----- */
var hamburger = document.getElementById('hamburger');
var navMenu   = document.getElementById('nav-menu');
if (hamburger && navMenu) {
  hamburger.addEventListener('click', function() {
    navMenu.classList.toggle('open');
  });
}

/* ----- 비밀번호 강도 측정기 ----- */
function checkStrength(pwd) {
  var criteria = [
    { id: 'c-length',  test: pwd.length >= 12 },
    { id: 'c-upper',   test: /[A-Z]/.test(pwd) },
    { id: 'c-lower',   test: /[a-z]/.test(pwd) },
    { id: 'c-number',  test: /[0-9]/.test(pwd) },
    { id: 'c-special', test: /[^A-Za-z0-9]/.test(pwd) }
  ];
  var score = 0;
  criteria.forEach(function(c) {
    var el = document.getElementById(c.id);
    if (el) {
      if (c.test) { el.classList.add('met'); score++; }
      else { el.classList.remove('met'); }
    }
  });
  var fill  = document.getElementById('strength-fill');
  var label = document.getElementById('strength-label');
  if (!fill || !label) return;
  var pct = (score / 5) * 100;
  fill.style.width = pct + '%';
  var levels = [
    { color: '#f43f5e', text: '매우 취약' },
    { color: '#f97316', text: '취약' },
    { color: '#eab308', text: '보통' },
    { color: '#3b82f6', text: '강함' },
    { color: '#10b981', text: '매우 강함' }
  ];
  var level = score > 0 ? levels[score - 1] : levels[0];
  fill.style.background = level.color;
  label.style.color     = level.color;
  label.textContent = '비밀번호 강도: ' + level.text;
}

/* ----- 비밀번호 입력 이벤트 (실시간 강도 측정) ----- */
var pwdInput = document.getElementById('password-input');
var strengthMeter = document.getElementById('strength-meter');
if (pwdInput && strengthMeter) {
  pwdInput.addEventListener('input', function() {
    if (this.value.length > 0) {
      strengthMeter.classList.add('visible');
      checkStrength(this.value);
    } else {
      strengthMeter.classList.remove('visible');
    }
  });
}

/* ----- 비밀번호 유출 검사 폼 ----- */
var pwdForm = document.getElementById('password-checker-form');
if (pwdForm) {
  pwdForm.addEventListener('submit', async function(e) {
    e.preventDefault();
    var pwd = document.getElementById('password-input').value;
    var res = document.getElementById('result-container');
    res.innerHTML = '<div style="color:var(--primary-color);text-align:center;padding:2rem;font-weight:700;">글로벌 보안 데이터베이스 대조 중...</div>';
    try {
      var hashBuffer = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(pwd));
      var hash = Array.from(new Uint8Array(hashBuffer))
        .map(function(b){ return b.toString(16).padStart(2,'0'); }).join('').toUpperCase();
      var prefix = hash.slice(0, 5);
      var suffix = hash.slice(5);
      var response = await fetch('https://api.pwnedpasswords.com/range/' + prefix);
      var data = await response.text();
      var match = data.split('\n').find(function(line){ return line.startsWith(suffix); });
      if (match) {
        var count = match.split(':')[1].trim();
        res.innerHTML = '<div style="color:#f43f5e;margin-top:2rem;padding:2.5rem;background:rgba(244,63,94,0.1);border-radius:24px;border:2px solid #f43f5e;text-align:center;">'
          + '<h3 style="color:#f43f5e;margin-bottom:1.5rem;font-size:1.8rem;">&#9888;&#65039; 유출 위험 감지</h3>'
          + '<p style="color:#f43f5e;font-size:1.2rem;">해당 비밀번호는 약 <strong>' + parseInt(count).toLocaleString() + '번</strong>의 데이터 유출 사고에서 발견되었습니다.</p>'
          + '<p style="margin-top:1rem;color:var(--text-color);">타 사이트에서 동일한 암호를 사용 중이라면 즉시 변경이 필요합니다.</p>'
          + '<button onclick="showSection(\'guide\')" style="margin-top:2rem;padding:0.8rem 2rem;border-radius:12px;border:none;background:#f43f5e;color:white;cursor:pointer;font-weight:800;">즉시 대처 방법 보기</button>'
          + '</div>';
      } else {
        res.innerHTML = '<div style="color:#10b981;margin-top:2rem;padding:2.5rem;background:rgba(16,185,129,0.1);border-radius:24px;border:2px solid #10b981;text-align:center;">'
          + '<h3 style="color:#10b981;margin-bottom:1.5rem;font-size:1.8rem;">&#10004;&#65039; 안전함</h3>'
          + '<p style="color:#10b981;font-size:1.2rem;">현재까지 알려진 데이터 유출 사고에서 해당 비밀번호는 발견되지 않았습니다.</p>'
          + '<p style="margin-top:0.75rem;color:var(--text-muted);">하지만 정기적으로 재확인하고, 비밀번호 강도도 함께 점검하세요.</p>'
          + '</div>';
      }
    } catch(err) {
      res.innerHTML = '<div style="color:#f43f5e;text-align:center;padding:2rem;">보안 서버 통신 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.</div>';
    }
  });
}

/* ----- 이메일 체크 폼 ----- */
var emailForm = document.getElementById('email-checker-form');
if (emailForm) {
  emailForm.addEventListener('submit', function(e) {
    e.preventDefault();
    var email = document.getElementById('email-input').value;
    var res   = document.getElementById('email-result');
    res.innerHTML = '<div style="color:var(--primary-color);text-align:center;padding:1.5rem;font-weight:700;">HIBP 사이트를 새 탭으로 여는 중...</div>';
    window.open('https://haveibeenpwned.com/?q=' + encodeURIComponent(email), '_blank');
    setTimeout(function() {
      res.innerHTML = '<div style="margin-top:1.5rem;padding:2rem;background:rgba(56,189,248,0.05);border-radius:20px;border:1px solid var(--primary-color);">'
        + '<h3 style="color:var(--primary-color);margin-bottom:1rem;">&#128203; 결과 해석 가이드</h3>'
        + '<p>방금 열린 HIBP 페이지에서 <strong>' + email + '</strong>의 유출 여부가 표시됩니다.</p>'
        + '<p style="margin-top:1rem;"><strong style="color:#f43f5e;">&#128308; 빨간색 결과</strong> &rarr; 해당 이메일이 포함된 유출 서비스 목록이 나타납니다. 해당 서비스의 비밀번호를 즉시 변경하고 MFA를 활성화하세요.</p>'
        + '<p style="margin-top:0.5rem;"><strong style="color:#10b981;">&#128994; 초록색 결과</strong> &rarr; 현재까지 알려진 유출 사고에서 발견되지 않았습니다. 정기적으로 재확인을 권장합니다.</p>'
        + '</div>';
    }, 900);
  });
}

/* ----- 다크/라이트 모드 토글 ----- */
var toggle = document.getElementById('theme-toggle');
if (toggle) {
  toggle.addEventListener('click', function() {
    document.body.classList.toggle('light-mode');
    localStorage.setItem('theme', document.body.classList.contains('light-mode') ? 'light' : 'dark');
  });
}
if (localStorage.getItem('theme') === 'light') {
  document.body.classList.add('light-mode');
}

/* ----- Disqus ----- */
(function() {
  var d = document, s = d.createElement('script');
  s.src = 'https://https-yanghyunmo44-hub-github-io-coding-practive.disqus.com/embed.js';
  s.setAttribute('data-timestamp', +new Date());
